<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue'
import { BarChart3, Coins, MessageSquareText, Plus, Search, ShieldAlert, TrendingUp, Users, Vote } from 'lucide-vue-next'
import { apiRequest } from '../lib/api'

const props=defineProps<{serverId:string}>()
interface Player { id:string;server_id:string;name:string;status:string;role:string;balance:number;playtime_hours:number;ping:number }
interface Feedback { id:string;server_id:string;player:string;content:string;category:string;sentiment:string;status:string }
interface Option { id:string;label:string;votes:number }
interface Poll { id:string;server_id:string;title:string;status:string;options:Option[];closes_at:string }
const players=ref<Player[]>([]),feedback=ref<Feedback[]>([]),polls=ref<Poll[]>([]),inflation=ref(0),query=ref(''),notice=ref(''),cluster=ref<any>(null),showPoll=ref(false),pollTitle=ref(''),pollOptions=ref(['',''])
const serverPlayers=computed(()=>players.value.filter(player=>player.server_id===props.serverId&&player.name.toLowerCase().includes(query.value.toLowerCase())))
const serverFeedback=computed(()=>feedback.value.filter(item=>item.server_id===props.serverId))
const serverPolls=computed(()=>polls.value.filter(poll=>poll.server_id===props.serverId))
const totalBalance=computed(()=>serverPlayers.value.reduce((sum,player)=>sum+player.balance,0))
async function load(){try{const data=await apiRequest<{players:Player[];feedback:Feedback[];polls:Poll[];inflation_rate:number}>('/api/community');players.value=data.players;feedback.value=data.feedback;polls.value=data.polls;inflation.value=data.inflation_rate}catch(error){notice.value=String(error)}}
async function previewAction(player:Player){const data=await apiRequest<{message:string}>('/api/players/'+player.id+'/action',{method:'POST',body:JSON.stringify({action:'warn',reason:'社区规则提醒',execute:false})});notice.value=player.name+'：'+data.message}
async function clusterFeedback(){cluster.value=await apiRequest<any>('/api/feedback/cluster',{method:'POST'});notice.value='已完成 '+serverFeedback.value.length+' 条意见聚类'}
async function createPoll(){const options=pollOptions.value.filter(option=>option.trim());if(!pollTitle.value.trim()||options.length<2)return;await apiRequest<Poll>('/api/polls',{method:'POST',body:JSON.stringify({server_id:props.serverId,title:pollTitle.value,options})});pollTitle.value='';pollOptions.value=['',''];showPoll.value=false;await load()}
async function voteFor(poll:Poll,option:Option){await apiRequest<Poll>('/api/polls/'+poll.id+'/vote',{method:'POST',body:JSON.stringify({option_id:option.id})});await load()}
watch(()=>props.serverId,load);onMounted(load)
</script>

<template>
  <div class="community-scroll">
    <section class="community-hero"><div><span><Users/></span><p><small>PLAYER COMMUNITY</small><b>玩家与社区运营</b><em>统一管理玩家、经济、意见与玩法投票。</em></p></div><button @click="showPoll=!showPoll"><Plus/>发起玩法投票</button></section>
    <div class="economy-grid"><article><span class="mint"><Users/></span><p><small>在线玩家</small><b>{{serverPlayers.filter(player=>player.status==='online').length}}</b><em>当前服务器</em></p></article><article><span class="amber"><Coins/></span><p><small>玩家总资产</small><b>{{totalBalance.toLocaleString()}}</b><em>绿宝石</em></p></article><article><span class="rose"><TrendingUp/></span><p><small>通胀率</small><b>{{inflation}}%</b><em>过去 24 小时</em></p></article><article><span class="violet"><MessageSquareText/></span><p><small>待处理意见</small><b>{{serverFeedback.filter(item=>item.status==='new').length}}</b><em>AI 可自动聚类</em></p></article></div>
    <section v-if="showPoll" class="poll-creator"><header><div><small>NEW POLL</small><b>创建玩法投票</b></div></header><input v-model="pollTitle" placeholder="投票标题"/><div class="option-inputs"><input v-for="(_,index) in pollOptions" :key="index" v-model="pollOptions[index]" :placeholder="'选项 '+(index+1)"/></div><footer><button @click="pollOptions.push('')"><Plus/>添加选项</button><button class="primary" @click="createPoll"><Vote/>发布投票</button></footer></section>
    <div class="content-grid">
      <section class="players-card"><header><div><small>玩家管理</small><b>玩家列表</b></div><label><Search/><input v-model="query" placeholder="搜索玩家"/></label></header><div class="player-table"><div class="table-head"><span>玩家</span><span>身份</span><span>余额</span><span>游戏时长</span><span>状态</span><span></span></div><article v-for="player in serverPlayers" :key="player.id"><span class="player-name"><i>{{player.name.slice(0,1)}}</i><b>{{player.name}}</b></span><span>{{player.role}}</span><span>{{player.balance.toLocaleString()}}</span><span>{{player.playtime_hours}}h</span><span class="player-status" :class="player.status">{{player.status==='online'?player.ping+' ms':player.status==='banned'?'已封禁':'离线'}}</span><button @click="previewAction(player)"><ShieldAlert/>操作预览</button></article></div></section>
      <aside>
        <section class="feedback-card"><header><div><small>意见收集</small><b>玩家反馈</b></div><button @click="clusterFeedback"><BarChart3/>AI 聚类</button></header><article v-for="item in serverFeedback" :key="item.id"><span :class="item.sentiment"></span><p><b>{{item.player}} · {{item.category}}</b><small>{{item.content}}</small></p></article><div v-if="cluster" class="cluster-result"><b>{{cluster.summary}}</b><span><i v-for="(count,name) in cluster.categories" :key="name">{{name}} {{count}}</i></span></div></section>
        <section class="poll-card"><header><div><small>进行中</small><b>玩法投票</b></div><Vote/></header><article v-for="poll in serverPolls" :key="poll.id"><b>{{poll.title}}</b><button v-for="option in poll.options" :key="option.id" @click="voteFor(poll,option)"><span>{{option.label}}</span><em>{{option.votes}} 票</em></button></article></section>
      </aside>
    </div>
    <div v-if="notice" class="toast">{{notice}}</div>
  </div>
</template>

<style scoped>
