card header>svg{width:13px}.feedback-card>article{display:flex;gap:8px;padding:9px 0;border-top:1px solid rgba(255,255,255,.055)}.feedback-card>article>span{width:6px;height:6px;margin-top:3px;border-radius:50%;background:#818c98}.feedback-card>article>span.positive{background:#32d5b0}.feedback-card>article>span.negative{background:#ff747b}.feedback-card>article p{display:flex;flex-direction:column;margin:0}.feedback-card>article b{font-size:8px}.feedback-card>article small{margin-top:4px;color:#687480;font-size:7px;line-height:1.5}.cluster-result{padding:9px;border-radius:7px;color:#9bcfc3;background:rgba(50,213,176,.05);font-size:7px;line-height:1.5}.cluster-result span{display:flex;flex-wrap:wrap;gap:4px;margin-top:6px}.cluster-result i{padding:2px 4px;border-radius:4px;background:rgba(50,213,176,.07);font-style:normal}.poll-card>article>b{display:block;margin-bottom:8px;font-size:9px}.poll-card>article>button{width:100%;display:flex;justify-content:space-between;padding:7px 8px;margin-top:5px;border:1px solid rgba(255,255,255,.065);border-radius:6px;color:#87929f;background:#0e1318;font-size:7px}.poll-card>article>button:hover{border-color:rgba(156,140,255,.2)}.poll-card em{color:#a69bf4;font-style:normal}.poll-creator{margin-top:10px}.poll-creator>input,.option-inputs input{height:31px;padding:0 9px;border:1px solid rgba(255,255,255,.08);border-radius:6px;outline:0;color:#cbd2da;background:#0e1318;font-size:8px}.poll-creator>input{width:100%}.option-inputs{display:grid;grid-template-columns:repeat(2,1fr);gap:7px;margin-top:7px}.poll-creator footer{display:flex;justify-content:flex-end;gap:6px;margin-top:9px}.poll-creator footer button{height:27px;display:flex;align-items:center;gap:4px;padding:0 8px;border:1px solid rgba(255,255,255,.08);border-radius:6px;color:#85909d;background:#171d24;font-size:7px}.poll-creator footer button.primary{border:0;color:#161121;background:#a89cff}.poll-creator footer svg{width:11px}.toast{position:sticky;bottom:10px;width:max-content;max-width:80%;padding:7px 10px;margin:10px auto 0;border:1px solid rgba(50,213,176,.18);border-radius:7px;color:#86dfca;background:#13211f;font-size:8px}@media(max-width:1100px){.economy-grid{grid-template-columns:repeat(2,1fr)}.content-grid{grid-template-columns:1fr}.table-head,.player-table article{grid-template-columns:1.3fr .7fr .7fr .7fr}.table-head span:nth-child(5),.table-head span:nth-child(6),.player-table article>*:nth-child(5),.player-table article>*:nth-child(6){display:none}}
